from pathlib import Path
from concurrent.futures import ThreadPoolExecutor, as_completed
from grounded_agency.capabilities.registry import CapabilityRegistry

P = Path("schemas/capability_ontology.yaml")
fails, first = 0, None
for attempt in range(80):
    reg = CapabilityRegistry(P)
    errs = []
    def probe(_):
        try:
            if reg.get_capability("retrieve") is None:
                errs.append("get_capability('retrieve') returned None")
        except Exception as e:
            errs.append(f"{type(e).__name__}: {e}")
    with ThreadPoolExecutor(max_workers=16) as pool:
        for f in as_completed([pool.submit(probe, i) for i in range(16)]):
            f.result()
    if errs:
        fails += 1
        first = first or (attempt, errs[0])
print("  first failure:", first)
print(f"  reproduced in {fails}/80 attempts")
PY

